    patchProject: {
        parameters: {
            query?: {
                /** @description The name of the project — or the id of the user — being destroyed. Without it the endpoint changes nothing and answers with a preview; a value that does not match is a 400 that also changes nothing. */
                confirm?: components["parameters"]["Confirm"];
            };
            header?: never;
            path: {
                id: components["parameters"]["ProjectID"];
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @description Admin token only */
                    name?: string;
                    /** @description How long a trace is kept after it arrived; null keeps it forever. Bounded because a window becomes a nanosecond cutoff, and a large enough one would overflow into the future and match every row — "forever" is null, not a big number. */
                    retention_days?: number | null;
                    /** @description The window for stored OTLP bodies; null follows retention_days */
                    raw_retention_days?: number | null;
                    /** @description The window for the hourly statistics rollup, measured by the hour a row summarizes; null keeps it forever, which is the default. The rollup outlives the traces it summarizes, so shortening this window destroys history the trace sweep spares — it asks for the same confirmation the other two do. */
                    stats_retention_days?: number | null;
                };
            };
        };
        responses: {
            /** @description The project as it is now, or the dry run of a window that shrinks */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Project"] | components["schemas"]["DryRun"];
                };
            };
            400: components["responses"]["BadRequest"];
            401: components["responses"]["Unauthorized"];
            403: components["responses"]["Forbidden"];
            404: components["responses"]["NotFound"];
            409: components["responses"]["Conflict"];
        };
    };
